export const cruiseScript = "\nconst LOGO=\"data:image/png;base64,\";\ndocument.getElementById('mlogo').src=LOGO;\n\n/* dateline + clock */\nfunction tickClock(){const d=new Date();\n  document.getElementById('dateline').textContent=d.toLocaleDateString('en-IN',{weekday:'long',year:'numeric',month:'long',day:'numeric'});\n  document.getElementById('clock').textContent=d.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',second:'2-digit'})+' IST';}\nsetInterval(tickClock,1000);tickClock();\n\n/* ticker */\nconst metrics=[[\"15,000+\",\"trips monitored daily\"],[\"< 5 min\",\"avg response time\"],[\"98%+\",\"exceptions identified\"],[\"24\u00d77\",\"zero missed overnight\"],[\"85%+\",\"AI-agent call success\"],[\"70%\",\"less manpower\"],[\"7\",\"regional languages\"],[\"3\u20134 hr\",\"SLA breach foresight\"]];\n(function(){let h=\"\";for(let r=0;r<2;r++)metrics.forEach(m=>h+=`<span><b>${m[0]}</b> ${m[1]} <i class=\"s\">\u25c6</i></span>`);document.getElementById('tick').innerHTML=h;})();\n\n/* ============ animated workflow diagram ============ */\n(function(){\n  const NS=\"http://www.w3.org/2000/svg\";\n  const svg=document.getElementById('flow');\n  const INK=\"#1A1A18\", PAPER=\"#FAF8F2\", NAVY=\"#A8B0D8\", ORANGE=\"#E8923C\", SAGE=\"#9DBE8E\", SOFT=\"#F2C98A\";\n  // background grid\n  let bg=`<rect width=\"480\" height=\"470\" fill=\"${PAPER}\"/>`;\n  for(let x=0;x<480;x+=16)bg+=`<line x1=\"${x}\" y1=\"0\" x2=\"${x}\" y2=\"470\" stroke=\"#000\" stroke-width=\"0.3\" opacity=\"0.025\"/>`;\n  for(let y=0;y<470;y+=16)bg+=`<line x1=\"0\" y1=\"${y}\" x2=\"480\" y2=\"${y}\" stroke=\"#000\" stroke-width=\"0.3\" opacity=\"0.025\"/>`;\n  svg.innerHTML=bg;\n\n  const cx=240;\n  // stage definitions: y-center, label, sublabel\n  const stages=[\n    {y:54, n:\"1 \u00b7 DETECT\",   s:\"Anomaly vs contextual baseline\"},\n    {y:134,n:\"2 \u00b7 DIAGNOSE\", s:\"Classify type \u00b7 severity \u00b7 cause\"},\n    {y:214,n:\"3 \u00b7 RESOLVE\",  s:\"Choose the action path\"},\n  ];\n  const boxW=300, boxH=52;\n\n  // connector pipeline (vertical spine) drawn first\n  const spine=document.createElementNS(NS,'g');svg.appendChild(spine);\n  function vline(y1,y2){const l=document.createElementNS(NS,'line');\n    l.setAttribute('x1',cx);l.setAttribute('y1',y1);l.setAttribute('x2',cx);l.setAttribute('y2',y2);\n    l.setAttribute('stroke',INK);l.setAttribute('stroke-width','1.5');spine.appendChild(l);}\n  vline(80,108);vline(160,188);vline(240,272);\n\n  // stage boxes\n  const boxEls=[];\n  stages.forEach(st=>{\n    const g=document.createElementNS(NS,'g');\n    g.innerHTML=`<rect x=\"${cx-boxW/2}\" y=\"${st.y-boxH/2}\" width=\"${boxW}\" height=\"${boxH}\" rx=\"3\" fill=\"${INK}\"/>\n      <circle cx=\"${cx-boxW/2+26}\" cy=\"${st.y}\" r=\"11\" fill=\"${SOFT}\" class=\"badge\"/>\n      <text x=\"${cx}\" y=\"${st.y-5}\" text-anchor=\"middle\" font-family=\"Oswald\" font-size=\"13\" font-weight=\"600\" fill=\"${PAPER}\" letter-spacing=\"1\">${st.n}</text>\n      <text x=\"${cx}\" y=\"${st.y+12}\" text-anchor=\"middle\" font-family=\"Oswald\" font-size=\"9.5\" fill=\"#bdb9ab\" letter-spacing=\"0.3\">${st.s}</text>`;\n    svg.appendChild(g);\n    boxEls.push({g,box:g.firstChild,y:st.y});\n  });\n\n  // EXECUTE label\n  const exY=292;\n  const exLabel=document.createElementNS(NS,'text');\n  exLabel.setAttribute('x',cx);exLabel.setAttribute('y',exY);exLabel.setAttribute('text-anchor','middle');\n  exLabel.setAttribute('font-family','Oswald');exLabel.setAttribute('font-size','12');exLabel.setAttribute('font-weight','600');\n  exLabel.setAttribute('letter-spacing','1');exLabel.setAttribute('fill',INK);\n  exLabel.textContent='4 \u00b7 EXECUTE';svg.appendChild(exLabel);\n\n  // three branch endpoints\n  const outY=386;\n  const outs=[\n    {x:84,  n:\"Vedika calls\",  s:\"regional language\", col:SOFT, dark:\"#9a6b2f\"},\n    {x:240, n:\"Self-resolve\",  s:\"no outreach\",        col:NAVY, dark:\"#3a4477\"},\n    {x:396, n:\"Ved escalates\", s:\"with context\",       col:SAGE, dark:\"#2f5a28\"},\n  ];\n  // branch connectors from execute label down to each box\n  const branchG=document.createElementNS(NS,'g');svg.appendChild(branchG);\n  outs.forEach(o=>{\n    const p=document.createElementNS(NS,'path');\n    p.setAttribute('d',`M${cx} ${exY+8} C ${cx} ${exY+34}, ${o.x} ${exY+18}, ${o.x} ${outY-26}`);\n    p.setAttribute('fill','none');p.setAttribute('stroke',INK);p.setAttribute('stroke-width','1.2');p.setAttribute('opacity','0.4');\n    branchG.appendChild(p);o._path=p;\n  });\n  // outcome boxes\n  const outEls=[];\n  outs.forEach(o=>{\n    const g=document.createElementNS(NS,'g');\n    g.innerHTML=`<rect x=\"${o.x-66}\" y=\"${outY-22}\" width=\"132\" height=\"56\" rx=\"3\" fill=\"${PAPER}\" stroke=\"${INK}\" stroke-width=\"1.2\"/>\n      <circle cx=\"${o.x}\" cy=\"${outY-4}\" r=\"8\" fill=\"${o.col}\" stroke=\"${INK}\" stroke-width=\"0.8\" class=\"oc\"/>\n      <text x=\"${o.x}\" y=\"${outY+16}\" text-anchor=\"middle\" font-family=\"Oswald\" font-size=\"11\" font-weight=\"600\" fill=\"${INK}\">${o.n}</text>\n      <text x=\"${o.x}\" y=\"${outY+28}\" text-anchor=\"middle\" font-family=\"Oswald\" font-size=\"8.5\" fill=\"#6F6A5C\">${o.s}</text>`;\n    svg.appendChild(g);outEls.push(g);\n  });\n\n  // resolved bar\n  const resY=448;\n  const resG=document.createElementNS(NS,'g');\n  resG.innerHTML=`<rect x=\"${cx-150}\" y=\"${resY-20}\" width=\"300\" height=\"34\" rx=\"3\" fill=\"${SAGE}\" opacity=\"0.25\" stroke=\"${INK}\" stroke-width=\"1\"/>\n    <text x=\"${cx}\" y=\"${resY+2}\" text-anchor=\"middle\" font-family=\"Oswald\" font-size=\"12\" font-weight=\"600\" letter-spacing=\"1\" fill=\"#2f5a28\">RESOLVED \u00b7 LOGGED \u00b7 AUDITED</text>`;\n  svg.appendChild(resG);\n  outs.forEach(o=>{const l=document.createElementNS(NS,'line');\n    l.setAttribute('x1',o.x);l.setAttribute('y1',outY+34);l.setAttribute('x2',cx);l.setAttribute('y2',resY-20);\n    l.setAttribute('stroke',INK);l.setAttribute('stroke-width','1');l.setAttribute('opacity','0.3');svg.appendChild(l);});\n\n  // moving token\n  const token=document.createElementNS(NS,'g');\n  token.innerHTML=`<circle r=\"9\" fill=\"none\" stroke=\"${ORANGE}\" stroke-width=\"2\"/><circle r=\"4.5\" fill=\"${SOFT}\" stroke=\"${INK}\" stroke-width=\"0.8\"/>`;\n  svg.appendChild(token);\n  const tRing=token.firstChild;\n\n  let resolved=0;const rc=document.getElementById('resolvedCount');\n\n  function flash(box){box.setAttribute('fill',ORANGE);\n    setTimeout(()=>box.setAttribute('fill',INK),520);}\n  function flashOut(g){const r=g.querySelector('.oc');const orig=r.getAttribute('fill');\n    r.setAttribute('fill',ORANGE);r.setAttribute('r','11');\n    setTimeout(()=>{r.setAttribute('fill',orig);r.setAttribute('r','8');},600);}\n\n  // animation sequence: detect -> diagnose -> resolve -> one branch -> resolved\n  const yPath=[54,134,214];      // stage centres\n  function runOnce(){\n    let pulse=0;const ring=setInterval(()=>{pulse=(pulse+1)%20;tRing.setAttribute('r',9+Math.sin(pulse/3)*1.5);},50);\n    const branch=Math.floor(Math.random()*3);\n    // keyframes: [x,y,settleMs,onArrive]\n    const kf=[\n      [cx,20,0,null],\n      [cx,54,420,()=>flash(boxEls[0].box)],\n      [cx,134,520,()=>flash(boxEls[1].box)],\n      [cx,214,520,()=>flash(boxEls[2].box)],\n      [cx,exY+4,420,null],\n      [outs[branch].x,outY-4,560,()=>flashOut(outEls[branch])],\n      [cx,resY-4,560,()=>{resolved++;rc.textContent=resolved+' resolved';\n        resG.firstChild.setAttribute('opacity','0.5');setTimeout(()=>resG.firstChild.setAttribute('opacity','0.25'),500);}],\n    ];\n    let i=0;\n    function step(){\n      if(i>=kf.length){clearInterval(ring);token.setAttribute('opacity','0');\n        setTimeout(()=>{token.setAttribute('opacity','1');runOnce();},700);return;}\n      const [x,y,dur,cb]=kf[i];\n      // animate from current to target\n      const cur=token.getAttribute('transform');\n      const m=cur?cur.match(/translate\\(([\\d.]+),([\\d.]+)\\)/):null;\n      const x0=m?+m[1]:x, y0=m?+m[2]:y;\n      const t0=performance.now();const D=Math.max(dur,260);\n      function tick(now){\n        const p=Math.min(1,(now-t0)/D);\n        const e=p<.5?2*p*p:1-Math.pow(-2*p+2,2)/2; // easeInOut\n        token.setAttribute('transform',`translate(${x0+(x-x0)*e},${y0+(y-y0)*e})`);\n        if(p<1)requestAnimationFrame(tick);\n        else{if(cb)cb();i++;setTimeout(()=>requestAnimationFrame(step),120);}\n      }\n      requestAnimationFrame(tick);\n    }\n    step();\n  }\n  token.setAttribute('transform',`translate(${cx},20)`);\n  runOnce();\n})();\n\n/* ============ live call transcript (with connecting state) ============ */\n(function(){\n  const scripts=[\n    {lang:\"\u0939\u093f\u0928\u094d\u0926\u0940\",title:\"Vedika \u2192 Driver \u00b7 Halt verification\",lines:[\n      [\"veda\",\"Vedika\",\"\u0928\u092e\u0938\u094d\u0924\u0947, \u091f\u094d\u0930\u0915 MH-12 \u0915\u0947 \u0921\u094d\u0930\u093e\u0907\u0935\u0930 \u091c\u0940?\"],[\"drv\",\"Driver\",\"\u0939\u093e\u0901 \u092c\u094b\u0932\u093f\u090f\u0964\"],\n      [\"veda\",\"Vedika\",\"\u0917\u093e\u0921\u093c\u0940 40 \u092e\u093f\u0928\u091f \u0938\u0947 \u0930\u0941\u0915\u0940 \u0939\u0948 \u2014 \u0938\u092c \u0920\u0940\u0915 \u0939\u0948?\"],[\"drv\",\"Driver\",\"\u0916\u093e\u0928\u093e \u0916\u093e \u0930\u0939\u093e \u0939\u0942\u0901, 15 \u092e\u093f\u0928\u091f \u092e\u0947\u0902 \u0928\u093f\u0915\u0932\u0924\u093e \u0939\u0942\u0901\u0964\"],\n      [\"veda\",\"Vedika\",\"\u0938\u092e\u091d \u0917\u0908\u0964 ETA \u0905\u092a\u0921\u0947\u091f \u0915\u0930 \u0930\u0939\u0940 \u0939\u0942\u0901\u0964 \u0927\u0928\u094d\u092f\u0935\u093e\u0926\u0964\"]]},\n    {lang:\"\u0ba4\u0bae\u0bbf\u0bb4\u0bcd\",title:\"Vedika \u2192 Driver \u00b7 Tracking gap\",lines:[\n      [\"veda\",\"Vedika\",\"\u0bb5\u0ba3\u0b95\u0bcd\u0b95\u0bae\u0bcd, \u0b9f\u0bbf\u0bb0\u0b95\u0bcd TN-28 \u0b9f\u0bbf\u0bb0\u0bc8\u0bb5\u0bb0\u0bbe?\"],[\"drv\",\"Driver\",\"\u0b86\u0bae\u0bbe \u0b9a\u0bca\u0bb2\u0bcd\u0bb2\u0bc1\u0b99\u0bcd\u0b95.\"],\n      [\"veda\",\"Vedika\",\"30 \u0ba8\u0bbf\u0bae\u0bbf\u0bb7\u0bae\u0bbe signal \u0b87\u0bb2\u0bcd\u0bb2 \u2014 \u0baa\u0bbf\u0bb0\u0b9a\u0bcd\u0b9a\u0bbf\u0ba9\u0bc8\u0baf\u0bbe?\"],[\"drv\",\"Driver\",\"\u0b9f\u0baf\u0bb0\u0bcd \u0b95\u0bbe\u0ba4\u0bcd\u0ba4\u0bc1, \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0b9e\u0bcd\u0b9a\u0bc1\u0b9f\u0bcd\u0b9f\u0bc7\u0ba9\u0bcd.\"],\n      [\"veda\",\"Vedika\",\"\u0ba8\u0bb2\u0bcd\u0bb2\u0ba4\u0bc1. ETA \u0b85\u0baa\u0bcd\u0b9f\u0bc7\u0b9f\u0bcd \u0baa\u0ba3\u0bcd\u0bb1\u0bc7\u0ba9\u0bcd. \u0ba8\u0ba9\u0bcd\u0bb1\u0bbf.\"]]},\n    {lang:\"\u092e\u0930\u093e\u0920\u0940\",title:\"Vedika \u2192 Driver \u00b7 Route deviation\",lines:[\n      [\"veda\",\"Vedika\",\"\u0928\u092e\u0938\u094d\u0915\u093e\u0930, \u091f\u094d\u0930\u0915 GJ-01 \u091a\u0947 \u0921\u094d\u0930\u093e\u092f\u0935\u094d\u0939\u0930?\"],[\"drv\",\"Driver\",\"\u0939\u094b, \u092c\u094b\u0932\u093e.\"],\n      [\"veda\",\"Vedika\",\"\u0930\u0942\u091f \u092c\u0926\u0932\u0932\u093e \u0906\u0939\u0947 \u2014 \u0938\u0930\u094d\u0935 \u0920\u0940\u0915 \u0906\u0939\u0947 \u0915\u093e?\"],[\"drv\",\"Driver\",\"\u0921\u093e\u092f\u0935\u094d\u0939\u0930\u094d\u0936\u0928 \u0939\u094b\u0924\u0902, \u0906\u0924\u093e \u092e\u093e\u0930\u094d\u0917\u093e\u0935\u0930 \u0906\u0939\u0947.\"],\n      [\"veda\",\"Vedika\",\"\u0920\u0940\u0915. \u0928\u094b\u0902\u0926 \u0915\u0947\u0932\u0940. \u0927\u0928\u094d\u092f\u0935\u093e\u0926.\"]]}\n  ];\n  let si=0;\n  const box=document.getElementById('callLines'),stamp=document.getElementById('callStamp');\n  const titleEl=document.getElementById('callTitle'),langEl=document.getElementById('callLang'),timerEl=document.getElementById('callTimer');\n  function run(){\n    const sc=scripts[si%scripts.length];si++;\n    box.innerHTML=\"\";stamp.classList.remove('show');\n    titleEl.textContent=\"Fig. 2 \u2014 \"+sc.title;langEl.textContent=sc.lang;\n    // connecting state\n    const conn=document.createElement('div');conn.className='line show';conn.style.color='#6F76A0';\n    conn.innerHTML='<span class=\"who\">Connecting\u2026</span> <span class=\"typing\"><i></i><i></i><i></i></span>';\n    box.appendChild(conn);\n    let secs=0;const tm=setInterval(()=>{secs++;timerEl.textContent='\u25cf '+secs+'s';},1000);\n    setTimeout(()=>{\n      conn.remove();\n      sc.lines.forEach((ln,i)=>{\n        const d=document.createElement('div');d.className='line '+ln[0];\n        d.innerHTML=`<span class=\"who\">${ln[1]}:</span> ${ln[2]}`;box.appendChild(d);\n        setTimeout(()=>d.classList.add('show'),i*1000);\n      });\n      setTimeout(()=>{stamp.classList.add('show');clearInterval(tm);\n        setTimeout(run,2600);\n      },sc.lines.length*1000+400);\n    },1300);\n  }\n  run();\n})();\n\n/* ============ signal fusion ============ */\n(function(){\n  const svg=document.getElementById('fusion');\n  const sigs=[[\"GPS\",55],[\"SIM\",92],[\"FASTag\",128],[\"IAS\",165]];\n  let h='<circle cx=\"250\" cy=\"100\" r=\"24\" fill=\"#A8B0D8\" stroke=\"#1A1A18\" stroke-width=\"1.5\"/><text x=\"250\" y=\"97\" font-family=\"Oswald\" font-size=\"9\" text-anchor=\"middle\">GROUND</text><text x=\"250\" y=\"108\" font-family=\"Oswald\" font-size=\"9\" text-anchor=\"middle\">TRUTH</text>';\n  sigs.forEach((s,i)=>{h+=`<line x1=\"64\" y1=\"${s[1]}\" x2=\"226\" y2=\"100\" stroke=\"#1A1A18\" stroke-width=\"1\" stroke-dasharray=\"2 2\" id=\"ln${i}\" opacity=\"0.55\"/>`;\n    h+=`<circle cx=\"50\" cy=\"${s[1]}\" r=\"15\" fill=\"#FAF8F2\" stroke=\"#1A1A18\" stroke-width=\"1.2\"/><text x=\"50\" y=\"${s[1]+3}\" font-family=\"Oswald\" font-size=\"8\" text-anchor=\"middle\">${s[0]}</text>`;});\n  svg.innerHTML+=h;\n  const st=document.getElementById('fusionState');\n  setInterval(()=>{const i=Math.floor(Math.random()*4);const ln=document.getElementById('ln'+i);\n    ln.setAttribute('opacity','0.07');st.textContent=sigs[i][0]+' dropped \u00b7 holding';st.style.color='#9a6b2f';\n    setTimeout(()=>{ln.setAttribute('opacity','0.55');st.textContent='nominal';st.style.color='';},1500);},3200);\n})();\n\n/* view toggle */\nfunction showView(v){\n  const map={chr:'chronicle',calc:'calcTab',ref:'reference'};\n  ['chr','calc','ref'].forEach(k=>{document.getElementById(map[k]).style.display=(k===v)?'block':'none';});\n  document.getElementById('tabChrBtn').classList.toggle('on',v==='chr');\n  document.getElementById('tabCalcBtn').classList.toggle('on',v==='calc');\n  document.getElementById('tabRefBtn').classList.toggle('on',v==='ref');\n  window.scrollTo(0,0);\n}\n\n\n\n// ---- fixed human timing assumptions ----\nconst LEAVE=2.5, WDAYS=25, CALLS_DAY=130;\n\nconst $=id=>document.getElementById(id);\nconst ids=[\"trips\",\"days\",\"apt\",\"cpa\",\"mpc\",\"rate\",\n  \"ppl\",\"sal\",\"other\",\"span\",\"supsal\",\"train\",\"attr\",\n  \"c0\",\"k0\",\"p0\",\"c1\",\"k1\",\"p1\",\"c2\",\"k2\",\"p2s\",\"c3\",\"k3\",\"p3\"];\n\n// Pool 2 categories: [eventsId, costId, prevId, %incurCost(fixed)]\nconst CATS=[\n  {ev:\"c0\",k:\"k0\",p:\"p0\",pct:0.40},\n  {ev:\"c1\",k:\"k1\",p:\"p1\",pct:0.35},\n  {ev:\"c2\",k:\"k2\",p:\"p2s\",pct:0.30},\n  {ev:\"c3\",k:\"k3\",p:\"p3\",pct:0.60},\n];\n\nconst fmtN=n=>Math.round(n).toLocaleString('en-IN');\nconst fmtR2=n=>\"\u20b9\"+(Math.round(n*100)/100).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});\nconst fmtRk=n=>{n=Math.round(n);\n  if(Math.abs(n)>=1e7)return \"\u20b9\"+(n/1e7).toFixed(2)+\" Cr\";\n  if(Math.abs(n)>=1e5)return \"\u20b9\"+(n/1e5).toFixed(2)+\" L\";\n  return \"\u20b9\"+n.toLocaleString('en-IN');};\n\nfunction setTrack(el){const mn=+el.min,mx=+el.max,p=((+el.value-mn)/(mx-mn))*100;el.style.setProperty('--p',p+'%');}\n\nfunction calc(){\n  const trips=+$(\"trips\").value, days=+$(\"days\").value, apt=+$(\"apt\").value;\n  const cpa=+$(\"cpa\").value, mpc=+$(\"mpc\").value, rate=+$(\"rate\").value;\n  const ppl=+$(\"ppl\").value, sal=+$(\"sal\").value, other=+$(\"other\").value, span=+$(\"span\").value;\n  const supsal=+$(\"supsal\").value, train=+$(\"train\").value, attr=+$(\"attr\").value/100;\n\n  // volume\n  const ttd=trips*days;\n  const alerts=trips*apt;\n  const calls=alerts*cpa;\n  const mins=calls*mpc;\n\n  // Cruise price \u2014 anchored on \u20b9/min\n  const price=mins*rate;\n  const perCall=calls>0?price/calls:0, perAlert=alerts>0?price/alerts:0;\n  const perTrip=trips>0?price/trips:0, perTripDay=ttd>0?price/ttd:0;\n\n  // Human fully-loaded cost\n  const sups=ppl>0?Math.ceil(ppl/span):0;\n  const people=ppl+sups;\n  const salaries=ppl*sal;                    // salary incl. infra & welfare\n  const otherCost=calls*other;               // per-call infra/calling/misc\n  const supCost=sups*supsal;\n  const trainCost=ppl*attr*train/12;\n  const humanTotal=salaries+otherCost+supCost+trainCost;\n  const effCalls=CALLS_DAY*(WDAYS-LEAVE);\n  const humanCapacity=Math.round(ppl*effCalls);\n  // current cost per unit\n  const hMin=mins>0?humanTotal/mins:0, hCall=calls>0?humanTotal/calls:0, hAlert=alerts>0?humanTotal/alerts:0;\n  const hTrip=trips>0?humanTotal/trips:0, hTripDay=ttd>0?humanTotal/ttd:0;\n\n  // Pool 1 & Pool 2\n  const pool1 = humanTotal - price;\n  const lossM = CATS.map(C=> (trips/100)*(+$(C.ev).value)*C.pct*(+$(C.k).value)*(+$(C.p).value/100));\n  const pool2 = lossM.reduce((a,b)=>a+b,0);\n  const totalValue = humanTotal + pool2;\n  const netBenefit = totalValue - price;\n  const roiMult = price>0 ? totalValue/price : 0;\n\n  // ticker\n  $(\"ticker\").innerHTML =\n    chip(fmtN(ttd),\"trip-days / mo\")+chip(fmtN(alerts),\"alerts / mo\")+\n    chip(fmtN(calls),\"calls / mo\")+chip(fmtN(mins)+\" min\",\"talk-time / mo\");\n\n  // verdict\n  const v=$(\"verdict\");\n  $(\"roiBig\").textContent=roiMult.toFixed(1)+\"\u00d7 return\";\n  $(\"roiNote\").textContent = netBenefit>=0\n    ? \"Net \"+fmtRk(netBenefit)+\" / month after paying for Cruise \u2014 \"+fmtRk(netBenefit*12)+\" a year.\"\n    : \"Above your current spend at this price. Adjust the per-minute rate or volume.\";\n  v.classList.toggle('neg', netBenefit<0);\n\n  // Cruise price block\n  $(\"pbMonthly\").textContent=fmtRk(price)+\" / mo\";\n  $(\"pMin\").textContent=fmtR2(rate); $(\"pCall\").textContent=fmtR2(perCall); $(\"pAlert\").textContent=fmtR2(perAlert);\n  $(\"pTrip\").textContent=fmtR2(perTrip); $(\"pTripDay\").textContent=fmtR2(perTripDay); $(\"pYear\").textContent=fmtRk(price*12);\n  $(\"pricehint\").textContent=\"At \u20b9\"+rate+\"/min \u2192 \"+fmtRk(price)+\" per month for \"+fmtN(mins)+\" minutes.\";\n\n  // Current cost block\n  $(\"cbMonthly\").textContent=fmtRk(humanTotal)+\" / mo\";\n  $(\"cMin\").textContent=fmtR2(hMin); $(\"cCall\").textContent=fmtR2(hCall); $(\"cAlert\").textContent=fmtR2(hAlert);\n  $(\"cTrip\").textContent=fmtR2(hTrip); $(\"cTripDay\").textContent=fmtR2(hTripDay); $(\"cYear\").textContent=fmtRk(humanTotal*12);\n\n  // cards\n  $(\"cHuman\").textContent=fmtRk(humanTotal);\n  $(\"cPrice\").textContent=fmtRk(price);\n  $(\"cSave\").textContent=fmtRk(netBenefit);\n  $(\"cSave\").style.color = netBenefit>=0 ? \"\" : \"#9a3b30\";\n  $(\"cPool1\").textContent=fmtRk(Math.max(0,pool1));\n  $(\"cPool2\").textContent=fmtRk(pool2);\n  $(\"cROI\").textContent=roiMult.toFixed(1)+\"\u00d7\";\n\n  // human vs AI\n  $(\"hPeople\").textContent=fmtN(people);\n  $(\"hCalls\").textContent=fmtN(humanCapacity);\n  $(\"aCalls\").textContent=fmtN(calls);\n  $(\"hConc\").textContent=fmtN(Math.max(1,ppl));\n  $(\"hCost\").textContent=fmtRk(humanTotal);\n  $(\"aCost\").textContent=fmtRk(price);\n  $(\"q1\").innerHTML=tick()+\"24\u00d77\u00d7365 \u2014 no night shift, no festival gap\";\n  $(\"q2\").innerHTML=tick()+\"Instant scaling \u2014 no hiring lag at volume spikes\";\n  $(\"q3\").innerHTML=tick()+\"Every call logged &amp; transcribed \u2014 audit-ready\";\n  $(\"q4\").innerHTML=tick()+\"No leave cover, attrition backfill or retraining\";\n\n  // pool 2 breakdown\n  $(\"p2Total\").textContent=fmtRk(pool2)+\" / mo\";\n  [\"l0\",\"l1\",\"l2\",\"l3\"].forEach((k,i)=>{$(k+\"m\").textContent=fmtRk(lossM[i]);$(k+\"y\").textContent=fmtRk(lossM[i]*12);});\n\n  $(\"dRate\").textContent=rate;\n}\n\nfunction chip(v,l){return '<span class=\"chip\"><span class=\"dot\"></span><b>'+v+'</b> '+l+'</span>';}\nfunction tick(){return '<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M5 13l4 4L19 7\" stroke=\"#2f5a28\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>';}\n\nfunction syncLabels(){\n  $(\"v_trips\").textContent=fmtN(+$(\"trips\").value);\n  $(\"v_days\").textContent=(+$(\"days\").value).toFixed(1);\n  $(\"v_apt\").textContent=(+$(\"apt\").value).toFixed(2);\n  $(\"v_cpa\").textContent=(+$(\"cpa\").value).toFixed(1);\n  $(\"v_mpc\").textContent=(+$(\"mpc\").value).toFixed(1);\n  $(\"v_rate\").textContent=(+$(\"rate\").value).toFixed(1);\n  $(\"v_ppl\").textContent=fmtN(+$(\"ppl\").value);\n  $(\"v_sal\").textContent=fmtN(+$(\"sal\").value);\n  $(\"v_other\").textContent=(+$(\"other\").value).toFixed(2);\n  $(\"v_span\").textContent=fmtN(+$(\"span\").value);\n  $(\"v_supsal\").textContent=fmtN(+$(\"supsal\").value);\n  $(\"v_train\").textContent=fmtN(+$(\"train\").value);\n  $(\"v_attr\").textContent=(+$(\"attr\").value);\n  [[\"v_c0\",\"c0\"],[\"v_k0\",\"k0\"],[\"v_p0\",\"p0\"],[\"v_c1\",\"c1\"],[\"v_k1\",\"k1\"],[\"v_p1\",\"p1\"],\n   [\"v_c2\",\"c2\"],[\"v_k2\",\"k2\"],[\"v_p2\",\"p2s\"],[\"v_c3\",\"c3\"],[\"v_k3\",\"k3\"],[\"v_p3\",\"p3\"]].forEach(([lab,id])=>{\n    const el=$(id); if(!el)return; const val=+el.value;\n    $(lab).textContent = (id.startsWith('k')) ? fmtN(val) : val;\n  });\n}\n\nfunction refresh(){ids.forEach(i=>{const el=$(i);if(el)setTrack(el);});syncLabels();calc();}\nids.forEach(i=>{const el=$(i);if(el)el.addEventListener('input',refresh);});\nrefresh();\n";
